import { describe, expect, it } from 'vitest';
import { buildUserTokenUnavailableBody, PrivateAppUserTokenUnavailableError, tokenUnavailableHint, } from '../../serverless/errors.js';
describe('serverless/errors', () => {
    describe('PrivateAppUserTokenUnavailableError', () => {
        it('exposes the expected fields and name', () => {
            const cause = new Error('boom');
            const err = new PrivateAppUserTokenUnavailableError('no token available', {
                hint: 'set PRIVATE_APP_ACCESS_TOKEN in your .env',
                cause,
                httpDetail: '401 { "error": "unauthorized" }',
            });
            expect(err).toBeInstanceOf(Error);
            expect(err.name).toBe('PrivateAppUserTokenUnavailableError');
            expect(err.message).toBe('no token available');
            expect(err.code).toBe('PRIVATE_APP_USER_TOKEN_UNAVAILABLE');
            expect(err.hint).toBe('set PRIVATE_APP_ACCESS_TOKEN in your .env');
            expect(err.httpDetail).toBe('401 { "error": "unauthorized" }');
            expect(err.cause).toBe(cause);
        });
        it('allows httpDetail and cause to be omitted', () => {
            const err = new PrivateAppUserTokenUnavailableError('no token', {
                hint: 'go set it',
            });
            expect(err.httpDetail).toBeUndefined();
            expect(err.cause).toBeUndefined();
            expect(err.hint).toBe('go set it');
        });
    });
    describe('tokenUnavailableHint', () => {
        it('defaults to PRIVATE_APP_ACCESS_TOKEN for legacy platform versions', () => {
            expect(tokenUnavailableHint()).toMatch(/PRIVATE_APP_ACCESS_TOKEN/);
            expect(tokenUnavailableHint()).toMatch(/\.env/);
        });
        it('names HUBSPOT_ACCESS_TOKEN for 2027.03+ / unstable', () => {
            expect(tokenUnavailableHint('HUBSPOT_ACCESS_TOKEN')).toMatch(/HUBSPOT_ACCESS_TOKEN/);
            expect(tokenUnavailableHint('HUBSPOT_ACCESS_TOKEN')).toMatch(/\.env/);
        });
    });
    describe('buildUserTokenUnavailableBody', () => {
        it('produces a structured body with the error fields', () => {
            const err = new PrivateAppUserTokenUnavailableError('no token', {
                hint: 'set it',
            });
            expect(buildUserTokenUnavailableBody(err)).toEqual({
                status: 'error',
                code: 'PRIVATE_APP_USER_TOKEN_UNAVAILABLE',
                message: 'no token',
                hint: 'set it',
                correlationId: 'n/a',
            });
        });
    });
});
